--
-- ============================================================================================
-- WHAT IS NOT WRITTEN, AND WHY
-- ============================================================================================
-- **106 candidates AP lists that we do not hold at all.** We cannot mark a loss against a row
-- that does not exist. Mostly minor parties and named write-ins (Grn 18, Oth 17, Lib 16, Ind 14, WCP 7, GOP 6, UST 6, NPA 5, Dem 4, Unr 2, AFi 2, NWk 2, NLP 1, NP 1, Con 1, PAG 1, CST 1, Una 1, Prg 1).
-- ▶ 10 of them took over 5% and are real contenders missing from our field:
--   NC-11   Jennifer Balkcom (GOP) 41.3%, 141,427 votes
--   LA-01   Lauren Jewett (Dem) 33.95%, 89,428 votes
--   VA-11   Arthur Purves (GOP) 24.38%, 81,357 votes
--   GA-04   Jim Duffie (GOP) 17.36%, 45,619 votes
--   LA-02   Peter Williams (GOP) 15.12%, 36,367 votes
--   NY-15   Andre Easton (Oth) 8.71%, 10,647 votes
--   MT-02   Michael Eisenhauer (Ind) 7.8%, 17,003 votes
--   LA-03   Priscilla Gonzalez (Dem) 7.16%, 16,828 votes
--   LA-03   Kate Cotten (GOP) 6.66%, 15,661 votes
--   PA-03   Dennis Mahoney (Ind) 6.41%, 17,298 votes
--
-- **406 of our rows in called races that AP's ballot does not list.** Untouched.
--   190 are already `not_nominated` - primary losers, correctly absent from a general ballot,
--      and the strongest evidence that this match is doing what it claims.
--   215 carry NO result at all. They are either unflagged primary losers or minor general
--      candidates AP omits, and AP cannot tell those apart. ▶ Separating them needs the state's
--      own ballot, not this feed.
--   1 is `withdrew`.
--
-- ============================================================================================
-- 🔴 104 ROWS HAVE A VALUE OVERWRITTEN, AND THIS IS WHAT IT WAS
-- ============================================================================================
-- 104 of the 599 losers already carry `result = 'advanced'` with `result_certainty = NULL`,
-- written by the ballot-qualification pass and each sourced to a state candidate list. There is
-- no history table, so an UPDATE is final.
--
--   OLD VALUE, ALL 104 ROWS:  result = 'advanced',  result_certainty = NULL
--   NEW VALUE:                  result = 'lost',      result_certainty = 'called'
--
-- As in `CC_0350`, the old citation is NOT discarded: the AP call is written and the previous
-- source appended verbatim in the same column, and a gate fails if any row lost it. The
-- before-values are committed at `backend/data/federal-2026-losers/before-values.json`.

CREATE TEMP TABLE ap_losers (scope text, seat_key text, seat text, rc_id uuid, our_last text, src text) ON COMMIT DROP;
;

-- Every US Senate and US House candidate row on the 2026-11-03 ballot.
CREATE TEMP TABLE fed_2026 ON COMMIT DROP AS
SELECT CASE WHEN d.district_type = 'NATIONAL_UPPER' THEN 'S' ELSE 'H' END AS scope,
       CASE WHEN d.district_type = 'NATIONAL_UPPER' THEN upper(d.state) ELSE d.geo_id END AS seat_key,
       d.geo_id, r.id AS race_id, rc.id AS rc_id, p.full_name, p.last_name,
       rc.result AS result_before, rc.result_source AS source_before
  FROM essentials.races r
  JOIN essentials.elections e ON e.id = r.election_id
  JOIN essentials.offices   o ON o.id = r.office_id
  JOIN essentials.districts d ON d.id = o.district_id
  JOIN essentials.race_candidates rc ON rc.race_id = r.id
  JOIN essentials.politicians p ON p.id = rc.politician_id
 WHERE e.election_date = DATE '2026-11-03'
   AND d.district_type IN ('NATIONAL_UPPER','NATIONAL_LOWER');

-- 🔴 THE PIN IS SELF-CHECKING: the id must sit in the stated race AND carry the stated surname.
CREATE TEMP TABLE loser_rows ON COMMIT DROP AS
SELECT a.seat, a.src, f.rc_id, f.race_id, f.full_name, f.result_before, f.source_before
  FROM ap_losers a
  JOIN fed_2026 f ON f.rc_id = a.rc_id
                 AND f.scope = a.scope
                 AND f.seat_key = a.seat_key
                 AND f.last_name = a.our_last;

UPDATE essentials.race_candidates rc
   SET result           = 'lost',
       result_certainty = 'called',
       result_source    = CASE
         WHEN w.source_before IS NULL OR btrim(w.source_before) = '' THEN w.src
         ELSE w.src || ' || PRIOR RESULT ' || quote_literal(coalesce(w.result_before, '(none)'))
              || ', SOURCED TO: ' || w.source_before
       END
  FROM loser_rows w
 WHERE rc.id = w.rc_id
   AND rc.result IS DISTINCT FROM 'lost';

DO $$
DECLARE
  v_file bigint; v_resolved bigint; v_lost bigint; v_cert bigint; v_prior bigint;
  v_lost_src bigint; v_was_won bigint; v_lindsey text; v_troy text;
  v_orphan_races bigint; v_orphan_geo text;
BEGIN
  SELECT count(*) INTO v_file FROM ap_losers;
  IF v_file <> 599 THEN RAISE EXCEPTION 'CC_0351: expected 599 rows in this file, found %', v_file; END IF;

  -- 🔴 A PIN THAT DOES NOT RESOLVE RETURNS A SMALLER SET, SILENTLY.
  SELECT count(*) INTO v_resolved FROM loser_rows;
  IF v_resolved <> 599 THEN
    RAISE EXCEPTION 'CC_0351: % row(s) resolved, expected 599 -- a pin that misses its race or surname drops out with no error', v_resolved;
  END IF;

  -- 🔴 NOBODY MAY BE DEMOTED FROM WINNER TO LOSER.
  SELECT count(*) INTO v_was_won FROM loser_rows WHERE result_before = 'won';
  IF v_was_won <> 0 THEN
    RAISE EXCEPTION 'CC_0351: % row(s) in this file are already marked won', v_was_won;
  END IF;

  SELECT count(*) INTO v_lost
    FROM essentials.race_candidates rc JOIN fed_2026 f ON f.rc_id = rc.id
   WHERE rc.result = 'lost';
  IF v_lost <> 599 THEN RAISE EXCEPTION 'CC_0351: expected 599 federal rows marked lost, found %', v_lost; END IF;

  SELECT count(*) INTO v_cert
    FROM essentials.race_candidates rc JOIN fed_2026 f ON f.rc_id = rc.id
   WHERE rc.result_certainty = 'certified';
  IF v_cert <> 0 THEN RAISE EXCEPTION 'CC_0351: % federal row(s) claim certification', v_cert; END IF;

  -- 🔴🔴 LINDSEY GRAHAM DIED BEFORE THE ELECTION AND WAS NOT ON THE BALLOT. HIS ROW STAYS NULL.
  SELECT coalesce(result, '(null)') INTO v_lindsey
    FROM essentials.race_candidates WHERE id = '71bafe26-3bb2-482c-b8db-ef7ead121365'::uuid;
  IF v_lindsey IS DISTINCT FROM '(null)' THEN
    RAISE EXCEPTION 'CC_0351: Lindsey Graham now carries result %, and he was not a candidate', v_lindsey;
  END IF;

  -- 🔴 TROY NEHLS DID NOT SEEK RE-ELECTION. HIS ROW STAYS NULL TOO.
  SELECT coalesce(result, '(null)') INTO v_troy
    FROM essentials.race_candidates WHERE id = '686d5b3a-a7df-4a67-bdba-d6b784181889'::uuid;
  IF v_troy IS DISTINCT FROM '(null)' THEN
    RAISE EXCEPTION 'CC_0351: Troy Nehls now carries result %, and he was not on the 2026 ballot', v_troy;
  END IF;

  -- 🔴 TX-22 IS THE ONLY RACE ALLOWED TO HAVE A LOSER AND NO WINNER.
  SELECT count(*), min(geo_id) INTO v_orphan_races, v_orphan_geo FROM (
    SELECT f.race_id, min(f.geo_id) AS geo_id
      FROM fed_2026 f JOIN essentials.race_candidates rc ON rc.id = f.rc_id
     GROUP BY f.race_id
    HAVING count(*) FILTER (WHERE rc.result = 'lost') > 0
       AND count(*) FILTER (WHERE rc.result = 'won')  = 0) x;
  IF v_orphan_races <> 1 OR v_orphan_geo IS DISTINCT FROM '4822' THEN
    RAISE EXCEPTION 'CC_0351: % race(s) carry a loser with no winner (first geo_id %); only TX-22 (4822) may', v_orphan_races, v_orphan_geo;
  END IF;

  -- 🔴 THE OVERWRITTEN CITATION MUST STILL BE IN THE ROW.
  SELECT count(*) INTO v_prior FROM loser_rows WHERE source_before IS NOT NULL AND btrim(source_before) <> '';
  IF v_prior <> 104 THEN
    RAISE EXCEPTION 'CC_0351: expected 104 rows carrying a prior result_source, found %', v_prior;
  END IF;

  SELECT count(*) INTO v_lost_src
    FROM essentials.race_candidates rc JOIN loser_rows w ON w.rc_id = rc.id
   WHERE w.source_before IS NOT NULL AND btrim(w.source_before) <> ''
     AND position(w.source_before in rc.result_source) = 0;
  IF v_lost_src <> 0 THEN
    RAISE EXCEPTION 'CC_0351: % row(s) lost the ballot-qualification citation they used to carry', v_lost_src;
  END IF;

  RAISE NOTICE 'CC_0351 OK: % losers recorded (76 Senate, 523 House); Lindsey Graham and Troy Nehls untouched', v_lost;
END $$;
